```sql
-- E-COMMERCE SALES ANALYSIS
-- STEP 6: COUNTRY ANALYSIS
-- Database: ecommerce_project

USE ecommerce_project;

-- 1. Revenue generated by each country
SELECT
    Country,
    ROUND(SUM(Quantity * UnitPrice), 2) AS Total_Revenue
FROM ecommerce_sales_analysis
GROUP BY Country
ORDER BY Total_Revenue DESC;

-- 2. Top 10 countries by revenue
SELECT
    Country,
    ROUND(SUM(Quantity * UnitPrice), 2) AS Total_Revenue
FROM ecommerce_sales_analysis
GROUP BY Country
ORDER BY Total_Revenue DESC
LIMIT 10;

-- 3. Orders received from each country
SELECT
    Country,
    COUNT(DISTINCT InvoiceNo) AS Total_Orders
FROM ecommerce_sales_analysis
GROUP BY Country
ORDER BY Total_Orders DESC;

-- 4. Units sold in each country
SELECT
    Country,
    SUM(Quantity) AS Total_Units_Sold
FROM ecommerce_sales_analysis
GROUP BY Country
ORDER BY Total_Units_Sold DESC;

-- 5. Average order value (AOV) by country
SELECT
    Country,
    COUNT(DISTINCT InvoiceNo) AS Total_Orders,
    ROUND(SUM(Quantity * UnitPrice), 2) AS Total_Revenue,
    ROUND(
        SUM(Quantity * UnitPrice) / COUNT(DISTINCT InvoiceNo),
        2
    ) AS Average_Order_Value
FROM ecommerce_sales_analysis
GROUP BY Country
ORDER BY Average_Order_Value DESC;
```